/**
 * Creates a debounced version of an async function with cancellation support.
 * 
 * - Only the last call within the delay window actually executes.
 * - Previous pending calls are cancelled and their promises reject with an AbortError.
 * - Returns a promise from each invocation so callers can await the result.
 * - Exposes a .cancel() method to manually cancel any pending execution.
 *
 * @param {Function} fn - Async function to debounce. Receives an AbortSignal as the last argument.
 * @param {number} delay - Debounce delay in milliseconds.
 * @returns {Function} Debounced function with .cancel() method.
 */
function debounceAsync(fn, delay) {
  let timeoutId = null;
  let abortController = null;

  function debounced(...args) {
    // Cancel any previously scheduled call
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    if (abortController) {
      abortController.abort();
    }

    // Create a new AbortController for this call
    abortController = new AbortController();
    const { signal } = abortController;

    return new Promise((resolve, reject) => {
      // Reject immediately if already aborted (defensive)
      signal.addEventListener('abort', () => {
        reject(new DOMException('Debounced call was cancelled', 'AbortError'));
      });

      timeoutId = setTimeout(async () => {
        timeoutId = null;
        // If aborted before the timeout fires, bail out
        if (signal.aborted) return;

        try {
          const result = await fn(...args, signal);
          if (!signal.aborted) {
            resolve(result);
          }
        } catch (err) {
          if (!signal.aborted) {
            reject(err);
          }
        }
      }, delay);
    });
  }

  debounced.cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (abortController) {
      abortController.abort();
      abortController = null;
    }
  };

  return debounced;
}
```

How it works:

1. Each call clears the previous timer and aborts the previous `AbortController`, so only the latest invocation within the delay window proceeds.
2. The wrapped function receives an `AbortSignal` as its last argument. You can pass that signal to `fetch` or any other cancellable API so in-flight network requests are actually cancelled at the transport level.
3. Callers get back a promise that resolves with the function's result, or rejects with an `AbortError` if a newer call supersedes it.
4. `.cancel()` lets you tear everything down manually (useful on component unmount, for example).

Usage example:

```javascript
const fetchUsers = debounceAsync(async (query, signal) => {
  const res = await fetch(`/api/users?q=${encodeURIComponent(query)}`, { signal });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}, 300);

// In a search input handler
input.addEventListener('input', async (e) => {
  try {
    const users = await fetchUsers(e.target.value);
    renderResults(users);
  } catch (err) {
    if (err.name === 'AbortError') {
      // Superseded by a newer keystroke — safe to ignore
      return;
    }
    showError(err);
  }
});

// On cleanup
fetchUsers.cancel();
