            format!("value too large for i64: '{trimmed}'")
        }
        std::num::IntErrorKind::NegOverflow => {
            format!("value too small for i64: '{trimmed}'")
        }
        std::num::IntErrorKind::InvalidDigit => {
            format!("invalid character in input: '{trimmed}'")
        }
        _ => format!("failed to parse '{trimmed}': {e}"),
    })
}

