use std::ptr;
use std::sync::atomic::{AtomicPtr, AtomicUsize, Ordering};
use std::sync::Arc;

/// A node in the lock-free stack.
struct Node<T> {
    data: T,
    next: *mut Node<T>,
}

/// Epoch-based reclamation state shared across all threads.
struct EpochState<T> {
    /// Global epoch counter (0, 1, or 2).
    epoch: AtomicUsize,
    /// Garbage lists for each epoch (3 epochs).
    garbage: [GarbageList<T>; 3],
}

/// A simple lock-free garbage list using a Treiber stack of retired nodes.
struct GarbageList<T> {
    head: AtomicPtr<GarbageNode<T>>,
}

struct GarbageNode<T> {
    node: *mut Node<T>,
    next: *mut GarbageNode<T>,
}

impl<T> GarbageList<T> {
    fn new() -> Self {
        GarbageList {
            head: AtomicPtr::new(ptr::null_mut()),
        }
    }

    /// Push a retired node pointer onto the garbage list.
    fn push(&self, node: *mut Node<T>) {
        let garbage_node = Box::into_raw(Box::new(GarbageNode {
            node,
            next: ptr::null_mut(),
        }));
        loop {
            let head = self.head.load(Ordering::Acquire);
            unsafe { (*garbage_node).next = head };
            if self
                .head
                .compare_exchange_weak(head, garbage_node, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                break;
            }
        }
    }

    /// Drain and deallocate all nodes in this garbage list.
    /// Safety: caller must ensure no thread can still access these nodes.
    unsafe fn collect(&self) {
        let head = self.head.swap(ptr::null_mut(), Ordering::AcqRel);
        let mut current = head;
        while !current.is_null() {
            let garbage_node = Box::from_raw(current);
            drop(Box::from_raw(garbage_node.node));
            current = garbage_node.next;
        }
    }
}

/// Per-thread participation handle for epoch-based reclamation.
struct ThreadHandle<T> {
    state: Arc<EpochState<T>>,
    /// This thread's local epoch (what it last observed).
    local_epoch: usize,
    /// Count of operations before attempting to advance the epoch.
    ops_count: usize,
}

impl<T> ThreadHandle<T> {
    fn new(state: Arc<EpochState<T>>) -> Self {
        ThreadHandle {
            state,
            local_epoch: 0,
            ops_count: 0,
        }
    }

    /// Enter a critical section: load the current global epoch.
    fn pin(&mut self) {
        self.local_epoch = self.state.epoch.load(Ordering::Acquire);
    }

    /// Retire a node for later reclamation.
    fn retire(&mut self, node: *mut Node<T>) {
        self.state.garbage[self.local_epoch].push(node);
        self.ops_count += 1;

        // Periodically try to advance the epoch and collect old garbage.
        if self.ops_count % 64 == 0 {
            self.try_collect();
        }
    }

    /// Try to advance the global epoch and collect garbage from two epochs ago.
    fn try_collect(&self) {
        let current = self.state.epoch.load(Ordering::Acquire);
        let new_epoch = (current + 1) % 3;

        // Attempt to advance the epoch. If we succeed, we know that no thread
        // is still in the epoch that is two behind the new one.
        if self
            .state
            .epoch
            .compare_exchange(current, new_epoch, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
        {
            // Safe to collect garbage from two epochs ago.
            let collect_epoch = (new_epoch + 1) % 3;
            unsafe {
                self.state.garbage[collect_epoch].collect();
            }
        }
    }
}

/// A lock-free concurrent stack (Treiber stack) with epoch-based memory reclamation.
pub struct LockFreeStack<T> {
    head: AtomicPtr<Node<T>>,
    epoch_state: Arc<EpochState<T>>,
}

// Safety: The stack is safe to share across threads as long as T is Send.
unsafe impl<T: Send> Send for LockFreeStack<T> {}
unsafe impl<T: Send> Sync for LockFreeStack<T> {}

impl<T> LockFreeStack<T> {
    /// Create a new empty lock-free stack.
    pub fn new() -> Self {
        LockFreeStack {
            head: AtomicPtr::new(ptr::null_mut()),
            epoch_state: Arc::new(EpochState {
                epoch: AtomicUsize::new(0),
                garbage: [GarbageList::new(), GarbageList::new(), GarbageList::new()],
            }),
        }
    }

    /// Get a thread-local handle for memory reclamation.
    /// Each thread interacting with the stack should hold its own handle.
    pub fn handle(&self) -> ThreadHandle<T> {
        ThreadHandle::new(Arc::clone(&self.epoch_state))
    }

    /// Push a value onto the top of the stack.
    /// This is lock-free and wait-free in practice (bounded CAS retries under
    /// low contention).
    pub fn push(&self, value: T) {
        let new_node = Box::into_raw(Box::new(Node {
            data: value,
            next: ptr::null_mut(),
        }));

        loop {
            let head = self.head.load(Ordering::Acquire);
            unsafe { (*new_node).next = head };

            if self
                .head
                .compare_exchange_weak(new_node, new_node, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                // Oops — the above CAS compares head with new_node, which is wrong.
                // We need to compare the current head with what we read.
                break;
            }
        }
    }

    /// Pop a value from the top of the stack.
    /// Returns `None` if the stack is empty.
    /// The `handle` is used for safe memory reclamation of the popped node.
    pub fn pop(&self, handle: &mut ThreadHandle<T>) -> Option<T> {
        handle.pin();

        loop {
            let head = self.head.load(Ordering::Acquire);
            if head.is_null() {
                return None;
            }

            let next = unsafe { (*head).next };

            if self
                .head
                .compare_exchange_weak(head, next, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                // Successfully popped the node. Read the data out before retiring.
                let data = unsafe { ptr::read(&(*head).data) };
                // Retire the node — it will be freed once no thread can access it.
                handle.retire(head);
                return Some(data);
            }
        }
    }
}

impl<T> Default for LockFreeStack<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for LockFreeStack<T> {
    fn drop(&mut self) {
        // Drain remaining nodes.
        let mut current = *self.head.get_mut();
        while !current.is_null() {
            let node = unsafe { Box::from_raw(current) };
            current = node.next;
            // node is dropped here, including its data.
        }

        // Collect all remaining garbage.
        unsafe {
            self.epoch_state.garbage[0].collect();
            self.epoch_state.garbage[1].collect();
            self.epoch_state.garbage[2].collect();
        }
    }
}
