    fn test_empty_pop() {
        let stack: LockFreeStack<i32> = LockFreeStack::new();
        let mut handle = stack.handle();
        assert_eq!(stack.pop(&mut handle), None);
    }

    #[test]
    fn test_concurrent_push_pop() {
        let stack = Arc::new(LockFreeStack::new());
        let num_threads = 8;
        let ops_per_thread = 1000;

        // Spawn threads that push values.
        let mut handles = vec![];
        for t in 0..num_threads {
            let stack = Arc::clone(&stack);
            handles.push(thread::spawn(move || {
                for i in 0..ops_per_thread {
                    stack.push(t * ops_per_thread + i);
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }

        // Pop all values — we should get exactly num_threads * ops_per_thread items.
        let mut count = 0;
        let mut handle = stack.handle();
        while stack.pop(&mut handle).is_some() {
            count += 1;
        }
        assert_eq!(count, num_threads * ops_per_thread);
    }

    #[test]
    fn test_concurrent_mixed() {
        let stack = Arc::new(LockFreeStack::new());
        let num_threads = 4;
        let ops_per_thread = 500;

        let mut handles = vec![];
        for _ in 0..num_threads {
            let stack = Arc::clone(&stack);
            handles.push(thread::spawn(move || {
                let mut handle = stack.handle();
                let mut pushed = 0usize;
                let mut popped = 0usize;
                for i in 0..ops_per_thread {
                    stack.push(i);
                    pushed += 1;
                    if let Some(_) = stack.pop(&mut handle) {
                        popped += 1;
                    }
                }
                (pushed, popped)
            }));
        }

        let mut total_pushed = 0;
        let mut total_popped = 0;
        for h in handles {
            let (p, q) = h.join().unwrap();
            total_pushed += p;
            total_popped += q;
        }

        // Drain remaining.
        let mut handle = stack.handle();
        while stack.pop(&mut handle).is_some() {
            total_popped += 1;
        }

        assert_eq!(total_pushed, total_popped);
    }
