// Lexer

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;

  while (pos < input.length) {
    // Skip whitespace
    if (/\s/.test(input[pos])) {
      pos++;
      continue;
    }

    const start = pos;

    // String literal (single-quoted)
    if (input[pos] === "'") {
      pos++;
      let value = "";
      while (pos < input.length && input[pos] !== "'") {
        if (input[pos] === "'" && input[pos + 1] === "'") {
          value += "'";
          pos += 2;
        } else {
          value += input[pos];
          pos++;
        }
      }
      if (pos >= input.length) {
        throw new Error(`Unterminated string literal at position ${start}`);
      }
      pos++; // skip closing quote
      tokens.push({ type: "STRING", value, position: start });
      continue;
    }

    // Number
    if (/\d/.test(input[pos]) || (input[pos] === "-" && pos + 1 < input.length && /\d/.test(input[pos + 1]))) {
      let num = "";
      if (input[pos] === "-") {
        num += "-";
        pos++;
      }
      while (pos < input.length && /\d/.test(input[pos])) {
        num += input[pos];
        pos++;
      }
      if (pos < input.length && input[pos] === ".") {
        num += ".";
        pos++;
        while (pos < input.length && /\d/.test(input[pos])) {
          num += input[pos];
          pos++;
        }
      }
      tokens.push({ type: "NUMBER", value: num, position: start });
      continue;
    }

    // Operators (multi-char first)
    if (input[pos] === "!" && input[pos + 1] === "=") {
      tokens.push({ type: "OPERATOR", value: "!=", position: start });
      pos += 2;
      continue;
    }
    if (input[pos] === "<" && input[pos + 1] === "=") {
      tokens.push({ type: "OPERATOR", value: "<=", position: start });
      pos += 2;
      continue;
    }
    if (input[pos] === ">" && input[pos + 1] === "=") {
      tokens.push({ type: "OPERATOR", value: ">=", position: start });
      pos += 2;
      continue;
    }
    if (input[pos] === "=" || input[pos] === "<" || input[pos] === ">") {
      tokens.push({ type: "OPERATOR", value: input[pos], position: start });
      pos++;
      continue;
    }

    // Punctuation
    if (input[pos] === ",") {
      tokens.push({ type: "COMMA", value: ",", position: start });
      pos++;
      continue;
    }
    if (input[pos] === ".") {
      tokens.push({ type: "DOT", value: ".", position: start });
      pos++;
      continue;
    }
    if (input[pos] === "*") {
      tokens.push({ type: "STAR", value: "*", position: start });
      pos++;
      continue;
    }
    if (input[pos] === "(") {
      tokens.push({ type: "LPAREN", value: "(", position: start });
      pos++;
      continue;
    }
    if (input[pos] === ")") {
      tokens.push({ type: "RPAREN", value: ")", position: start });
      pos++;
      continue;
    }

    // Identifiers and keywords
    if (/[a-zA-Z_]/.test(input[pos])) {
      let ident = "";
      while (pos < input.length && /[a-zA-Z0-9_]/.test(input[pos])) {
        ident += input[pos];
        pos++;
      }
      const upper = ident.toUpperCase();
      if (KEYWORDS.has(upper)) {
        tokens.push({ type: "KEYWORD", value: upper, position: start });
      } else {
        tokens.push({ type: "IDENTIFIER", value: ident, position: start });
      }
      continue;
    }

    throw new Error(`Unexpected character '${input[pos]}' at position ${pos}`);
  }

  tokens.push({ type: "EOF", value: "", position: pos });
  return tokens;
}

// Parser

class Parser {
  private tokens: Token[];
  private pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  parse(): SelectStatement {
    const stmt = this.parseSelect();
    this.expect("EOF");
    return stmt;
  }

  private parseSelect(): SelectStatement {
    this.expectKeyword("SELECT");
    const columns = this.parseColumns();
    this.expectKeyword("FROM");
    const from = this.parseTableReference();
    const where = this.parseWhere();
    const orderBy = this.parseOrderBy();

    return {
      type: "SelectStatement",
      columns,
      from,
      where,
      orderBy,
    };
  }

  private parseColumns(): Column[] {
    const columns: Column[] = [];
    columns.push(this.parseColumn());

    while (this.peek().type === "COMMA") {
      this.advance(); // consume comma
      columns.push(this.parseColumn());
    }

    return columns;
  }

  private parseColumn(): Column {
    if (this.peek().type === "STAR") {
      this.advance();
      return { type: "Column", name: "*", alias: null };
    }

    let name = this.expectIdentifier();

    // Handle table.column notation
    if (this.peek().type === "DOT") {
      this.advance();
      if (this.peek().type === "STAR") {
        this.advance();
        name = `${name}.*`;
      } else {
        const col = this.expectIdentifier();
        name = `${name}.${col}`;
      }
    }

    // Handle alias
    let alias: string | null = null;
    if (this.peek().type === "KEYWORD" && this.peek().value === "AS") {
      this.advance();
      alias = this.expectIdentifier();
    } else if (
      this.peek().type === "IDENTIFIER" &&
      !this.isUpcomingClause()
    ) {
      alias = this.expectIdentifier();
    }

    return { type: "Column", name, alias };
  }

  private parseTableReference(): TableReference {
    const name = this.expectIdentifier();
    let alias: string | null = null;

    if (this.peek().type === "KEYWORD" && this.peek().value === "AS") {
      this.advance();
      alias = this.expectIdentifier();
    } else if (
      this.peek().type === "IDENTIFIER" &&
      !this.isUpcomingClause()
    ) {
      alias = this.expectIdentifier();
    }

    return { type: "TableReference", name, alias };
  }

  private parseWhere(): Expression | null {
    if (
      this.peek().type !== "KEYWORD" ||
      this.peek().value !== "WHERE"
    ) {
      return null;
    }
    this.advance(); // consume WHERE
    return this.parseOrExpression();
  }

  private parseOrExpression(): Expression {
    let left = this.parseAndExpression();

    while (
      this.peek().type === "KEYWORD" &&
      this.peek().value === "OR"
    ) {
      this.advance();
      const right = this.parseAndExpression();
      left = {
        type: "BinaryExpression",
        operator: "OR",
        left,
        right,
      };
    }

    return left;
  }

  private parseAndExpression(): Expression {
    let left = this.parseComparison();

    while (
      this.peek().type === "KEYWORD" &&
      this.peek().value === "AND"
    ) {
      this.advance();
      const right = this.parseComparison();
      left = {
        type: "BinaryExpression",
        operator: "AND",
        left,
        right,
      };
    }

    return left;
  }

  private parseComparison(): Expression {
    if (this.peek().type === "LPAREN") {
      this.advance();
      const expr = this.parseOrExpression();
      this.expectToken("RPAREN");
      return expr;
    }

    const left = this.parsePrimary();

    if (this.peek().type === "OPERATOR") {
      const op = this.advance().value as ComparisonExpression["operator"];
      const right = this.parsePrimary();
      return {
        type: "ComparisonExpression",
        operator: op,
        left,
        right,
      };
    }

    return left;
  }

  private parsePrimary(): Expression {
    const token = this.peek();

    if (token.type === "NUMBER") {
      this.advance();
      return {
        type: "Literal",
        value: token.value.includes(".")
          ? parseFloat(token.value)
          : parseInt(token.value, 10),
      };
    }

    if (token.type === "STRING") {
      this.advance();
      return { type: "Literal", value: token.value };
    }

    if (token.type === "KEYWORD" && token.value === "NULL") {
      this.advance();
      return { type: "Literal", value: null };
    }

    if (token.type === "IDENTIFIER") {
      this.advance();
      let table: string | null = null;
      let name = token.value;

      if (this.peek().type === "DOT") {
        this.advance();
        table = name;
        name = this.expectIdentifier();
      }

      return { type: "ColumnRef", name, table };
    }

    throw new Error(
      `Unexpected token '${token.value}' (${token.type}) at position ${token.position}`
    );
  }

  private parseOrderBy(): OrderByClause[] | null {
    if (
      this.peek().type !== "KEYWORD" ||
      this.peek().value !== "ORDER"
    ) {
      return null;
    }
    this.advance(); // consume ORDER
    this.expectKeyword("BY");

    const clauses: OrderByClause[] = [];
    clauses.push(this.parseOrderByClause());

    while (this.peek().type === "COMMA") {
      this.advance();
      clauses.push(this.parseOrderByClause());
    }

    return clauses;
  }

  private parseOrderByClause(): OrderByClause {
    const ident = this.expectIdentifier();
    let table: string | null = null;
    let name = ident;

    if (this.peek().type === "DOT") {
      this.advance();
      table = name;
      name = this.expectIdentifier();
    }

    let direction: "ASC" | "DESC" = "ASC";
    if (
      this.peek().type === "KEYWORD" &&
      (this.peek().value === "ASC" || this.peek().value === "DESC")
    ) {
      direction = this.advance().value as "ASC" | "DESC";
    }

    return {
      type: "OrderByClause",
      column: { type: "ColumnRef", name, table },
      direction,
    };
  }

  // Helpers

  private peek(): Token {
    return this.tokens[this.pos];
  }

  private advance(): Token {
    const token = this.tokens[this.pos];
    this.pos++;
    return token;
  }

  private expect(type: TokenType): Token {
    const token = this.peek();
    if (token.type !== type) {
      throw new Error(
        `Expected ${type} but got '${token.value}' (${token.type}) at position ${token.position}`
      );
    }
    return this.advance();
  }

  private expectToken(type: TokenType): Token {
    return this.expect(type);
  }

  private expectKeyword(keyword: string): Token {
    const token = this.peek();
    if (token.type !== "KEYWORD" || token.value !== keyword) {
      throw new Error(
        `Expected keyword '${keyword}' but got '${token.value}' at position ${token.position}`
      );
    }
    return this.advance();
  }

  private expectIdentifier(): string {
    const token = this.peek();
    if (token.type !== "IDENTIFIER") {
      throw new Error(
        `Expected identifier but got '${token.value}' (${token.type}) at position ${token.position}`
      );
    }
    this.advance();
    return token.value;
  }

  private isUpcomingClause(): boolean {
    const token = this.peek();
    if (token.type !== "KEYWORD") return false;
    return ["FROM", "WHERE", "ORDER", "AND", "OR"].includes(token.value);
  }
}

// Public API

function parseSQL(sql: string): SelectStatement {
  const tokens = tokenize(sql.trim());
  const parser = new Parser(tokens);
  return parser.parse();
}

// Demo

const sql = `SELECT u.id, u.name AS username, email FROM users u WHERE u.age >= 18 AND (status = 'active' OR role = 'admin') ORDER BY u.name ASC, u.id DESC`;

const ast = parseSQL(sql);
console.log(JSON.stringify(ast, null, 2));
