def solve_sudoku(board: list[list[int]]) -> list[list[int]]:
    """Solve a 9x9 Sudoku puzzle using constraint propagation and backtracking.

    Args:
        board: 9x9 grid where 0 represents empty cells.

    Returns:
        The solved board (modified in place and returned), or the original board
        if no solution exists.
    """

    def get_candidates(board, row, col):
        """Get possible values for a cell using constraint propagation."""
        if board[row][col] != 0:
            return set()

        candidates = set(range(1, 10))

        # Row constraint
        candidates -= set(board[row])

        # Column constraint
        candidates -= {board[r][col] for r in range(9)}

        # 3x3 box constraint
        box_row, box_col = 3 * (row // 3), 3 * (col // 3)
        for r in range(box_row, box_row + 3):
            for c in range(box_col, box_col + 3):
                candidates.discard(board[r][c])

        return candidates

    def propagate(board):
        """Apply constraint propagation repeatedly until no more progress."""
        changed = True
        while changed:
            changed = False
            for r in range(9):
                for c in range(9):
                    if board[r][c] == 0:
                        candidates = get_candidates(board, r, c)
                        if len(candidates) == 0:
                            return False  # Contradiction
                        if len(candidates) == 1:
                            board[r][c] = candidates.pop()
                            changed = True
        return True

    def solve(board):
        """Backtracking search with constraint propagation."""
        if not propagate(board):
            return False

        # Find the empty cell with the fewest candidates (MRV heuristic)
        min_candidates = None
        min_cell = None
        for r in range(9):
            for c in range(9):
                if board[r][c] == 0:
                    candidates = get_candidates(board, r, c)
                    if not candidates:
                        return False
                    if min_candidates is None or len(candidates) < len(min_candidates):
                        min_candidates = candidates
                        min_cell = (r, c)

        if min_cell is None:
            return True  # All cells filled

        row, col = min_cell
        for value in min_candidates:
            # Save state
            snapshot = [row[:] for row in board]

            board[row][col] = value
            if solve(board):
                return True

            # Restore state on failure
            for r in range(9):
                for c in range(9):
                    board[r][c] = snapshot[r][c]

        return False

    solve(board)
    return board
```

The function uses three key techniques:

- Constraint propagation: repeatedly fills cells that have only one possible value, pruning the search space before guessing.
- MRV heuristic (Minimum Remaining Values): when backtracking is needed, it picks the cell with the fewest candidates, which fails faster and reduces branching.
- Backtracking with state restoration: tries a candidate, recurses, and restores the board from a snapshot if the choice leads to a contradiction.

