  }

  // Circular reference check
  if (seen.has(obj)) {
    return seen.get(obj);
  }

  // Date
  if (obj instanceof Date) {
    const clone = new Date(obj.getTime());
    seen.set(obj, clone);
    return clone;
  }

  // RegExp
  if (obj instanceof RegExp) {
    const clone = new RegExp(obj.source, obj.flags);
    clone.lastIndex = obj.lastIndex;
    seen.set(obj, clone);
    return clone;
  }

  // ArrayBuffer
  if (obj instanceof ArrayBuffer) {
    const clone = obj.slice(0);
    seen.set(obj, clone);
    return clone;
  }

  // TypedArrays (Uint8Array, Float32Array, etc.)
  if (ArrayBuffer.isView(obj) && !(obj instanceof DataView)) {
    const clone = new obj.constructor(obj.buffer.slice(0));
    seen.set(obj, clone);
    return clone;
  }

  // DataView
  if (obj instanceof DataView) {
    const bufferClone = obj.buffer.slice(0);
    const clone = new DataView(bufferClone, obj.byteOffset, obj.byteLength);
    seen.set(obj, clone);
    return clone;
  }

  // Map
  if (obj instanceof Map) {
    const clone = new Map();
    seen.set(obj, clone);
    for (const [key, value] of obj) {
      clone.set(deepClone(key, seen), deepClone(value, seen));
    }
    return clone;
  }

  // Set
  if (obj instanceof Set) {
    const clone = new Set();
    seen.set(obj, clone);
    for (const value of obj) {
      clone.add(deepClone(value, seen));
    }
    return clone;
  }

  // Arrays and plain objects — preserve prototype chain
  const proto = Object.getPrototypeOf(obj);
  const clone = Array.isArray(obj) ? [] : Object.create(proto);
  seen.set(obj, clone);

  // Copy all own properties including symbols and non-enumerable ones
  const descriptors = Object.getOwnPropertyDescriptors(obj);
  for (const key of Reflect.ownKeys(descriptors)) {
    const desc = descriptors[key];
    if ('value' in desc) {
      Object.defineProperty(clone, key, {
        ...desc,
        value: deepClone(desc.value, seen),
      });
    } else {
      // Accessor properties (getters/setters) — copy as-is
      Object.defineProperty(clone, key, desc);
    }
  }

  return clone;
}
```

Key design decisions:

- **Circular references** are tracked with a `WeakMap` keyed by the original object. If we encounter the same object again, we return the already-created clone.
- **Prototype chains** are preserved via `Object.create(proto)` so instances of custom classes keep their inherited methods.
- **Property descriptors** are copied faithfully (enumerable, writable, configurable flags, plus symbol keys and non-enumerable properties). Accessor properties (getters/setters) are transferred without invoking them.
- **Map keys** are also deep-cloned, since keys can be objects with their own reference graphs.
- **TypedArrays and DataView** clone the underlying buffer so mutations don't leak between original and clone.

This is a solid implementation. A few observations:

There's a subtle race condition in the abort listener. When a previous call is superseded, `abortController.abort()` fires the `abort` event listener on the signal, which calls `reject()`. But if the timeout has already fired and `fn` is mid-execution, you could end up with both the abort listener calling `reject` and the catch block also trying to call `reject`. The second call is a no-op (promises settle once), so it won't throw, but it's worth being aware of.

A cleaner pattern is to remove the event listener approach and instead check abort status at each decision point:

```javascript
return new Promise((resolve, reject) => {
  timeoutId = setTimeout(async () => {
    timeoutId = null;
    if (signal.aborted) {
      reject(new DOMException('Debounced call was cancelled', 'AbortError'));
      return;
    }

    try {
      const result = await fn(...args, signal);
      if (signal.aborted) {
        reject(new DOMException('Debounced call was cancelled', 'AbortError'));
      } else {
        resolve(result);
      }
    } catch (err) {
      if (signal.aborted) {
        reject(new DOMException('Debounced call was cancelled', 'AbortError'));
      } else {
        reject(err);
      }
    }
  }, delay);

  // Handle abort that happens *before* the timeout fires
  signal.addEventListener('abort', () => {
    reject(new DOMException('Debounced call was cancelled', 'AbortError'));
  }, { once: true });
});
```

The `{ once: true }` avoids leaking listeners if the signal is long-lived.

One other thing: if `fn` itself throws synchronously (not async), the `await` in front of it will catch that in the try/catch, so you're fine there.

The API design is clean. Passing the signal as the last argument is the right call since it keeps the consumer in control of cancellation propagation without forcing a specific signature.

